from fractions import Fraction as _Fr

def duel(p, q):
    p, q = _Fr(p), _Fr(q)
    return p / (1 - (1 - p) * (1 - q))

from fractions import Fraction as _Fr
from itertools import combinations as _comb

def _avg(N, k):
    rows = [tank_estimates(list(s)) for s in _comb(range(1, N + 1), k)]
    return (sum(_Fr(r[0]) for r in rows) / len(rows), sum(_Fr(r[1]) for r in rows) / len(rows))
